CREATE TABLE `academic_terms` (
  `id` int(11) NOT NULL,
  `academic_year_id` int(11) NOT NULL,
  `name` varchar(50) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `is_current` tinyint(1) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `academic_years` (
  `id` int(11) NOT NULL,
  `name` varchar(20) NOT NULL COMMENT 'e.g., 2024-25',
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `is_current` tinyint(1) DEFAULT 0,
  `description` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Academic years management';

CREATE TABLE `attendance` (
  `id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `timetable_id` int(11) NOT NULL,
  `attendance_date` date NOT NULL,
  `status` enum('Present','Absent','Late') NOT NULL DEFAULT 'Absent',
  `marked_by` int(11) NOT NULL COMMENT 'Faculty ID who marked the attendance',
  `marked_at` timestamp NULL DEFAULT current_timestamp(),
  `remarks` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `attendance_logs` (
  `id` int(11) NOT NULL,
  `event_uuid` varchar(64) NOT NULL,
  `device_id` varchar(128) NOT NULL,
  `student_id` int(11) NOT NULL,
  `timetable_id` int(11) NOT NULL,
  `attendance_date` date NOT NULL,
  `status` enum('Present','Absent','Late') NOT NULL,
  `marked_by_user_id` int(11) NOT NULL,
  `marked_by_faculty_id` int(11) NOT NULL,
  `captured_at` datetime DEFAULT NULL,
  `confidence` decimal(5,4) DEFAULT NULL,
  `face_model` varchar(120) DEFAULT NULL,
  `detector_model` varchar(120) DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  `processing_status` enum('pending','processed','failed') NOT NULL DEFAULT 'pending',
  `error_message` varchar(500) DEFAULT NULL,
  `raw_payload` longtext DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `processed_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `audit_logs` (
  `id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `username` varchar(50) DEFAULT NULL,
  `action` varchar(100) NOT NULL,
  `entity_type` varchar(50) DEFAULT NULL COMMENT 'e.g., timetable, faculty, student, subject',
  `entity_id` int(11) DEFAULT NULL COMMENT 'ID of the affected record',
  `old_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Previous values before change' CHECK (json_valid(`old_values`)),
  `new_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'New values after change' CHECK (json_valid(`new_values`)),
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `request_method` varchar(10) DEFAULT NULL COMMENT 'GET, POST, PUT, DELETE',
  `request_url` text DEFAULT NULL,
  `status` varchar(20) DEFAULT 'success' COMMENT 'success, failed, error',
  `error_message` text DEFAULT NULL,
  `session_id` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `branding_settings` (
  `id` int(11) NOT NULL,
  `setting_key` varchar(100) NOT NULL,
  `setting_value` text DEFAULT NULL,
  `setting_type` varchar(50) DEFAULT 'text',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `classes` (
  `id` int(11) NOT NULL,
  `name` varchar(50) NOT NULL COMMENT 'FY, SY, TY, etc',
  `display_order` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Class/Year levels';

CREATE TABLE `courses` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `code` varchar(20) DEFAULT NULL,
  `program` enum('UG','PG') NOT NULL,
  `department_id` int(11) NOT NULL,
  `duration_years` int(11) DEFAULT 3,
  `total_semesters` int(11) DEFAULT 6,
  `description` text DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `lecture_duration_minutes` int(11) DEFAULT 60 COMMENT 'Default lecture duration for this course (PG: 60min, UG: 45min)',
  `max_sessions_per_day` int(11) DEFAULT 4 COMMENT 'Maximum sessions per day for this course',
  `course_level` enum('UG','PG','Diploma','Certificate') DEFAULT 'PG' COMMENT 'Course level determines lecture duration defaults'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Academic courses/programs';

CREATE TABLE `course_batches` (
  `id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `batch_name` varchar(50) NOT NULL,
  `academic_year_id` int(11) DEFAULT NULL,
  `start_year` year(4) NOT NULL,
  `end_year` year(4) NOT NULL,
  `total_students` int(11) DEFAULT 0,
  `current_semester` tinyint(4) DEFAULT 1,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  CONSTRAINT `chk_batch_years` CHECK (`end_year` >= `start_year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Course batch management for student groups';

CREATE TABLE `departments` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `code` varchar(20) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `head_of_department` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Academic departments';

CREATE TABLE `divisions` (
  `id` int(11) NOT NULL,
  `name` varchar(10) NOT NULL COMMENT 'A, B, C, etc',
  `capacity` int(11) DEFAULT 60,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  CONSTRAINT `chk_capacity` CHECK (`capacity` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Class divisions/sections';

CREATE TABLE `elective_groups` (
  `id` int(11) NOT NULL,
  `group_name` varchar(100) NOT NULL,
  `course_id` int(11) NOT NULL,
  `semester_id` int(11) NOT NULL,
  `min_subjects_to_choose` tinyint(4) DEFAULT 1,
  `max_subjects_to_choose` tinyint(4) DEFAULT 1,
  `total_credits` decimal(4,1) DEFAULT 0.0,
  `description` text DEFAULT NULL,
  `is_mandatory` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Elective subject groups for student selection';

CREATE TABLE `elective_group_subjects` (
  `id` int(11) NOT NULL,
  `elective_group_id` int(11) NOT NULL,
  `subject_id` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Subjects belonging to elective groups';

CREATE TABLE `encryption_keys` (
  `id` int(11) NOT NULL,
  `key_name` varchar(50) NOT NULL,
  `encrypted_key` text NOT NULL COMMENT 'Encrypted with master key',
  `algorithm` varchar(50) DEFAULT 'AES-256-CBC',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `rotated_at` timestamp NULL DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `faculty` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `department_id` int(11) NOT NULL,
  `designation` varchar(50) DEFAULT NULL,
  `qualification` varchar(100) DEFAULT NULL,
  `specialization` varchar(200) DEFAULT NULL,
  `max_hours_per_week` int(11) DEFAULT 24,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `user_id` int(11) NOT NULL,
  `employee_id` varchar(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Faculty members';

CREATE TABLE `faculty_absences` (
  `id` int(11) NOT NULL,
  `faculty_id` int(11) NOT NULL,
  `absence_date` date NOT NULL,
  `reason` text DEFAULT NULL,
  `status` enum('PROCESSED','UNPROCESSED') DEFAULT 'UNPROCESSED',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `faculty_allocations` (
  `id` int(11) NOT NULL,
  `faculty_id` int(11) NOT NULL,
  `subject_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `semester_id` int(11) DEFAULT NULL,
  `course_batch_id` int(11) DEFAULT NULL,
  `allocated_hours` decimal(4,1) DEFAULT 0.0,
  `workload_percentage` decimal(5,2) DEFAULT 100.00,
  `is_primary` tinyint(1) DEFAULT 1,
  `allocation_type` enum('Regular','Guest','Visiting','Part-time') DEFAULT 'Regular',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Faculty subject allocations with workload tracking';

CREATE TABLE `faculty_availability` (
  `id` int(11) NOT NULL,
  `faculty_id` int(11) NOT NULL,
  `day_of_week` tinyint(4) NOT NULL COMMENT '1=Monday, 7=Sunday',
  `is_available` tinyint(1) DEFAULT 1,
  `shift_pattern_id` int(11) DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Faculty weekly availability with shift templates and custom time slots. start_time/end_time can differ from shift times.';

CREATE TABLE `institution_holidays` (
  `id` int(11) NOT NULL,
  `holiday_date` date DEFAULT NULL,
  `day_of_week` enum('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday') DEFAULT NULL,
  `name` varchar(120) NOT NULL,
  `applies_to_program` enum('UG','PG','Both') DEFAULT 'Both',
  `is_recurring` tinyint(1) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `login_attempts` (
  `id` int(11) NOT NULL,
  `username` varchar(50) NOT NULL,
  `ip_address` varchar(45) NOT NULL,
  `user_agent` text DEFAULT NULL,
  `status` varchar(20) NOT NULL COMMENT 'success, failed, blocked',
  `failure_reason` varchar(100) DEFAULT NULL,
  `attempted_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `mobile_devices` (
  `id` int(11) NOT NULL,
  `device_id` varchar(128) NOT NULL,
  `device_name` varchar(150) DEFAULT NULL,
  `platform` varchar(80) DEFAULT NULL,
  `owner_user_id` int(11) DEFAULT NULL,
  `api_key_secret` varchar(255) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `rate_limit_per_minute` int(11) NOT NULL DEFAULT 120,
  `created_by_user_id` int(11) DEFAULT NULL,
  `last_used_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `mobile_face_templates` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `embedding_json` longtext NOT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `quality_score` decimal(5,4) DEFAULT NULL,
  `embedding_version` varchar(50) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `mobile_request_nonces` (
  `id` bigint(20) NOT NULL,
  `device_id` varchar(128) NOT NULL,
  `nonce` varchar(120) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `password_reset_requests` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `token` varchar(100) NOT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `used` tinyint(1) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `permissions` (
  `id` int(11) NOT NULL,
  `name` varchar(50) NOT NULL,
  `description` text DEFAULT NULL,
  `module` varchar(50) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `permission_groups` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `module` varchar(50) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `permission_group_permissions` (
  `id` int(11) NOT NULL,
  `group_id` int(11) NOT NULL,
  `permission_id` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `processed_reports` (
  `id` int(11) NOT NULL,
  `report_type` varchar(50) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'completed',
  `filters_json` text DEFAULT NULL,
  `row_count` int(11) NOT NULL DEFAULT 0,
  `file_name` varchar(255) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `downloaded_at` timestamp NULL DEFAULT NULL,
  `progress` tinyint(3) UNSIGNED NOT NULL DEFAULT 100
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proxy_assignments` (
  `id` int(11) NOT NULL,
  `original_faculty_id` int(11) NOT NULL,
  `proxy_faculty_id` int(11) NOT NULL,
  `subject_id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `day_of_week` varchar(20) DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `assignment_date` date NOT NULL,
  `reason` enum('absence','workload','expertise','manual') DEFAULT 'absence',
  `status` enum('pending','confirmed','rejected','completed') DEFAULT 'pending',
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `proxy_log` (
  `id` int(11) NOT NULL,
  `original_faculty_id` int(11) NOT NULL,
  `proxy_faculty_id` int(11) DEFAULT NULL,
  `timetable_id` int(11) NOT NULL,
  `absence_date` date NOT NULL,
  `status` enum('ASSIGNED','UNASSIGNED') NOT NULL,
  `approval_status` enum('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',
  `approval_date` datetime DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approval_notes` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `registration_invitations` (
  `id` int(11) NOT NULL,
  `token` varchar(64) NOT NULL,
  `email` varchar(100) NOT NULL,
  `role` varchar(50) NOT NULL,
  `name` varchar(100) DEFAULT NULL,
  `course_id` int(11) DEFAULT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `department_id` int(11) DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `expires_at` timestamp NULL DEFAULT NULL,
  `used_at` timestamp NULL DEFAULT NULL,
  `status` enum('pending','used','expired') DEFAULT 'pending'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `roles` (
  `id` int(11) NOT NULL,
  `name` varchar(50) NOT NULL,
  `description` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `hierarchy_level` int(11) NOT NULL DEFAULT 50
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `role_permissions` (
  `role_id` int(11) NOT NULL,
  `permission_id` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `rooms` (
  `id` int(11) NOT NULL,
  `room_number` varchar(20) NOT NULL,
  `room_type` enum('Classroom','Laboratory','Auditorium','Seminar Hall') DEFAULT 'Classroom',
  `capacity` int(11) DEFAULT 60,
  `department_id` int(11) DEFAULT NULL,
  `floor` int(11) DEFAULT NULL,
  `building` varchar(50) DEFAULT NULL,
  `has_projector` tinyint(1) DEFAULT 0,
  `has_ac` tinyint(1) DEFAULT 0,
  `is_available` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  CONSTRAINT `chk_room_capacity` CHECK (`capacity` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Classroom and lab information';

CREATE TABLE `semesters` (
  `id` int(11) NOT NULL,
  `academic_year_id` int(11) NOT NULL,
  `semester_number` tinyint(4) NOT NULL COMMENT 'Semester number (1-8)',
  `semester_name` varchar(50) NOT NULL COMMENT 'e.g., Semester I, Semester II',
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `is_current` tinyint(1) DEFAULT 0,
  `min_credits` decimal(4,1) DEFAULT 18.0,
  `max_credits` decimal(4,1) DEFAULT 30.0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `class_id` int(11) DEFAULT NULL COMMENT 'Links semester to class/year level',
  CONSTRAINT `chk_credits` CHECK (`max_credits` >= `min_credits`),
  CONSTRAINT `chk_semester_dates` CHECK (`end_date` > `start_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Semester management with credit requirements';

CREATE TABLE `shift_change_requests` (
  `id` int(11) NOT NULL,
  `faculty_id` int(11) NOT NULL,
  `day_of_week` tinyint(4) NOT NULL COMMENT '1=Monday, 7=Sunday',
  `current_shift_name` varchar(100) DEFAULT NULL,
  `requested_shift_name` varchar(100) NOT NULL,
  `reason` text DEFAULT NULL,
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `admin_response` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `shift_patterns` (
  `id` int(11) NOT NULL,
  `shift_name` varchar(100) NOT NULL,
  `shift_code` varchar(20) NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `shift_order` int(11) DEFAULT 1,
  `description` text DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `students` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `roll_number` varchar(50) DEFAULT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `course_batch_id` int(11) DEFAULT NULL,
  `admission_year` year(4) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `user_id` int(11) NOT NULL,
  `admission_id` varchar(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student information';

CREATE TABLE `student_subject_selections` (
  `id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `subject_id` int(11) NOT NULL,
  `elective_group_id` int(11) DEFAULT NULL,
  `semester_id` int(11) NOT NULL,
  `academic_year_id` int(11) NOT NULL,
  `selection_date` timestamp NULL DEFAULT current_timestamp(),
  `is_confirmed` tinyint(1) DEFAULT 0,
  `grade` varchar(2) DEFAULT NULL,
  `marks_obtained` decimal(5,2) DEFAULT NULL,
  `credits_earned` decimal(3,1) DEFAULT NULL,
  `status` enum('Enrolled','Completed','Failed','Withdrawn') DEFAULT 'Enrolled'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student subject selections and academic progress';

CREATE TABLE `subjects` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `course_code` varchar(20) NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `semester_id` int(11) DEFAULT NULL,
  `course_type` enum('Core','Elective','Core Practical','Elective Practical','Project','Internship','Dissertation') DEFAULT 'Core',
  `theory_practical` enum('Theory','Practical','Both') DEFAULT 'Theory',
  `credits` decimal(3,1) NOT NULL DEFAULT 3.0,
  `theory_credits` decimal(3,1) DEFAULT 0.0,
  `practical_credits` decimal(3,1) DEFAULT 0.0,
  `marks` int(11) DEFAULT 100,
  `theory_marks` int(11) DEFAULT 0,
  `practical_marks` int(11) DEFAULT 0,
  `lectures_per_week` tinyint(4) DEFAULT 3,
  `practical_hours_per_week` tinyint(4) DEFAULT 0,
  `is_elective` tinyint(1) DEFAULT 0,
  `description` text DEFAULT NULL,
  `syllabus_url` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  CONSTRAINT `chk_total_credits` CHECK (abs(`credits` - (`theory_credits` + `practical_credits`)) < 0.1),
  CONSTRAINT `chk_total_marks` CHECK (`marks` = `theory_marks` + `practical_marks`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Enhanced subjects with comprehensive academic details';

CREATE TABLE `timetable` (
  `id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) NOT NULL,
  `division_id` int(11) DEFAULT NULL,
  `day_of_week` enum('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday') NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `subject_id` int(11) NOT NULL,
  `faculty_id` int(11) NOT NULL,
  `room_id` int(11) DEFAULT NULL,
  `academic_year_id` int(11) DEFAULT NULL,
  `semester_id` int(11) DEFAULT NULL,
  `course_batch_id` int(11) DEFAULT NULL,
  `room_number` varchar(20) DEFAULT NULL,
  `timetable_type` enum('Regular','Exam','Special','Makeup') DEFAULT 'Regular',
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  CONSTRAINT `chk_time_slot` CHECK (`end_time` > `start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timetable schedule';

CREATE TABLE `timetable_conflicts` (
  `id` int(11) NOT NULL,
  `generation_timestamp` datetime NOT NULL DEFAULT current_timestamp(),
  `course_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `conflict_type` enum('faculty_collision','room_unavailable','faculty_unavailable','exceed_hours','no_slot') NOT NULL,
  `faculty_id` int(11) DEFAULT NULL,
  `subject_id` int(11) DEFAULT NULL,
  `day_of_week` varchar(20) DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `description` text DEFAULT NULL,
  `resolution_status` enum('unresolved','resolved','ignored') DEFAULT 'unresolved'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `timetable_generation_settings` (
  `id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `setting_key` varchar(100) NOT NULL,
  `setting_value` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `timetable_history` (
  `id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `day_of_week` varchar(20) DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `subject_id` int(11) DEFAULT NULL,
  `faculty_id` int(11) DEFAULT NULL,
  `room_id` int(11) DEFAULT NULL,
  `week_start_date` date DEFAULT NULL,
  `archived_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `timetable_jobs` (
  `id` int(11) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'queued',
  `progress` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `total_count` int(11) NOT NULL DEFAULT 0,
  `done_count` int(11) NOT NULL DEFAULT 0,
  `assigned_count` int(11) NOT NULL DEFAULT 0,
  `unassigned_count` int(11) NOT NULL DEFAULT 0,
  `failed_count` int(11) NOT NULL DEFAULT 0,
  `settings_json` mediumtext NOT NULL,
  `summary_json` mediumtext DEFAULT NULL,
  `message` varchar(300) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `finished_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `timetable_quality_candidates` (
  `id` int(11) NOT NULL,
  `run_id` varchar(64) NOT NULL,
  `candidate_index` int(11) NOT NULL,
  `is_selected` tinyint(1) NOT NULL DEFAULT 0,
  `quality_score` decimal(5,2) NOT NULL,
  `clash_risk` decimal(5,4) NOT NULL,
  `faculty_fatigue` decimal(5,4) NOT NULL,
  `room_overuse` decimal(5,4) NOT NULL,
  `student_load_imbalance` decimal(5,4) NOT NULL,
  `assigned_count` int(11) NOT NULL DEFAULT 0,
  `unassigned_count` int(11) NOT NULL DEFAULT 0,
  `needs_room_count` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `timetable_quality_runs` (
  `id` int(11) NOT NULL,
  `run_id` varchar(64) NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) NOT NULL,
  `division_id` int(11) NOT NULL,
  `week_start` date NOT NULL,
  `quality_score` decimal(5,2) NOT NULL,
  `clash_risk` decimal(5,4) NOT NULL,
  `faculty_fatigue` decimal(5,4) NOT NULL,
  `room_overuse` decimal(5,4) NOT NULL,
  `student_load_imbalance` decimal(5,4) NOT NULL,
  `candidate_count` int(11) NOT NULL DEFAULT 7,
  `selected_candidate_index` int(11) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `timetable_session_targets` (
  `id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `week_start_date` date NOT NULL,
  `target_sessions` int(11) NOT NULL DEFAULT 24 COMMENT 'Ideal number of sessions to schedule',
  `minimum_sessions` int(11) NOT NULL DEFAULT 20 COMMENT 'Minimum acceptable sessions',
  `actual_sessions` int(11) DEFAULT 0 COMMENT 'Actually scheduled sessions',
  `generation_status` enum('pending','in_progress','completed','failed') DEFAULT 'pending',
  `generation_timestamp` datetime DEFAULT NULL,
  `generation_notes` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `unscheduled_sessions_log` (
  `id` int(11) NOT NULL,
  `generation_timestamp` datetime NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) DEFAULT NULL,
  `division_id` int(11) DEFAULT NULL,
  `subject_id` int(11) NOT NULL,
  `session_type` enum('Theory','Practical','Both') DEFAULT 'Theory',
  `required_slots` int(11) DEFAULT 1,
